/**
 * Export script: parses the Three.js ferris wheel scene and writes
 * individual mesh OBJ files + merged part-link OBJ files.
 *
 * Usage: node --experimental-vm-modules export_meshes.mjs
 */

import * as THREE from 'three';
import fs from 'fs';
import path from 'path';

// ── helpers ──────────────────────────────────────────────────────────

/**
 * Convert a THREE.BufferGeometry (already in world space) to an OBJ string.
 */
function geometryToOBJ(geometry, name = 'mesh') {
    const pos = geometry.getAttribute('position');
    const idx = geometry.getIndex();
    let obj = `# ${name}\n`;

    // Vertices
    for (let i = 0; i < pos.count; i++) {
        obj += `v ${pos.getX(i)} ${pos.getY(i)} ${pos.getZ(i)}\n`;
    }

    // Normals (if present)
    const norm = geometry.getAttribute('normal');
    if (norm) {
        for (let i = 0; i < norm.count; i++) {
            obj += `vn ${norm.getX(i)} ${norm.getY(i)} ${norm.getZ(i)}\n`;
        }
    }

    // Faces
    if (idx) {
        for (let i = 0; i < idx.count; i += 3) {
            const a = idx.getX(i) + 1;
            const b = idx.getX(i + 1) + 1;
            const c = idx.getX(i + 2) + 1;
            if (norm) {
                obj += `f ${a}//${a} ${b}//${b} ${c}//${c}\n`;
            } else {
                obj += `f ${a} ${b} ${c}\n`;
            }
        }
    } else {
        // Non-indexed geometry
        for (let i = 0; i < pos.count; i += 3) {
            const a = i + 1;
            const b = i + 2;
            const c = i + 3;
            if (norm) {
                obj += `f ${a}//${a} ${b}//${b} ${c}//${c}\n`;
            } else {
                obj += `f ${a} ${b} ${c}\n`;
            }
        }
    }
    return obj;
}

/**
 * Bake world transform into a cloned geometry so the OBJ lives in world space.
 */
function bakeGeometry(mesh) {
    mesh.updateMatrixWorld(true);
    const geo = mesh.geometry.clone();
    geo.applyMatrix4(mesh.matrixWorld);
    return geo;
}

/**
 * Merge an array of BufferGeometries into one (simple concat).
 */
function mergeGeometries(geometries) {
    let totalVerts = 0;
    let totalIdx = 0;
    let hasNormals = true;

    for (const g of geometries) {
        totalVerts += g.getAttribute('position').count;
        if (g.getIndex()) totalIdx += g.getIndex().count;
        else totalIdx += g.getAttribute('position').count;
        if (!g.getAttribute('normal')) hasNormals = false;
    }

    const positions = new Float32Array(totalVerts * 3);
    const normals = hasNormals ? new Float32Array(totalVerts * 3) : null;
    const indices = new Uint32Array(totalIdx);

    let vOffset = 0;
    let iOffset = 0;
    let vertBase = 0;

    for (const g of geometries) {
        const pos = g.getAttribute('position');
