/**
 * Convert a THREE.BufferGeometry (already in world space) to an OBJ string.
 */
function geometryToOBJ(geometry, name = 'mesh') {
    const pos = geometry.getAttribute('position');
    const idx = geometry.getIndex();
    let obj = `# ${name}\n`;

    // Vertices
    for (let i = 0; i < pos.count; i++) {
        obj += `v ${pos.getX(i)} ${pos.getY(i)} ${pos.getZ(i)}\n`;
    }

    // Normals (if present)
    const norm = geometry.getAttribute('normal');
    if (norm) {
        for (let i = 0; i < norm.count; i++) {
            obj += `vn ${norm.getX(i)} ${norm.getY(i)} ${norm.getZ(i)}\n`;
        }
    }

    // Faces
    if (idx) {
        for (let i = 0; i < idx.count; i += 3) {
            const a = idx.getX(i) + 1;
            const b = idx.getX(i + 1) + 1;
            const c = idx.getX(i + 2) + 1;
            if (norm) {
                obj += `f ${a}//${a} ${b}//${b} ${c}//${c}\n`;
            } else {
                obj += `f ${a} ${b} ${c}\n`;
            }
        }
    } else {
        // Non-indexed geometry
        for (let i = 0; i < pos.count; i += 3) {
            const a = i + 1;
            const b = i + 2;
            const c = i + 3;
            if (norm) {
                obj += `f ${a}//${a} ${b}//${b} ${c}//${c}\n`;
            } else {
                obj += `f ${a} ${b} ${c}\n`;
            }
        }
    }
    return obj;
}

